class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        n = len(nums)
        if n < k:
            return -1
        count = {}
        for start in range(n - k + 1):
            for x in set(nums[start:start + k]):
                count[x] = count.get(x, 0) + 1
        ans = -1
        for x, c in count.items():
            if c == 1:
                ans = max(ans, x)
        return ans

