class Solution:
    def solveQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        n = len(nums)
        groups = defaultdict(list)
        for i, x in enumerate(nums):
            groups[x].append(i)

        index_ans = [-1] * n

        for x, idxs in groups.items():
            k = len(idxs)
            if k == 1:
                continue

            for p in range(k):
                i = idxs[p]
                nxt = idxs[(p + 1) % k]
                prv = idxs[(p - 1) % k]

                d1 = abs(nxt - i)
                if d1 > n - d1:
                    d1 = n - d1

                d2 = abs(i - prv)
                if d2 > n - d2:
                    d2 = n - d2

                index_ans[i] = d1 if d1 < d2 else d2

        return [index_ans[q] for q in queries]

