def solve_block(block):
    n = len(block)
    i = 0

    p = 0
    while i < n and block[i] == 'A':
        p += 1
        i += 1

    pairs = []
    q = 0  # trailing W-run length

    while i < n:
        a = 0
        while i < n and block[i] == 'W':
            a += 1
            i += 1

        b = 0
        while i < n and block[i] == 'A':
            b += 1
            i += 1

        if b == 0:
            q = a
            break

        pairs.append((a, b))

    parts = []
    if p:
        parts.append('A' * p)

    if not pairs:
        parts.append('W' * q)
        return ''.join(parts)

    # The processed W/A part begins with A.
    parts.append('A')
    m = len(pairs)
    for idx, (a, b) in enumerate(pairs):
        parts.append('C' * a)
        if idx < m - 1:
            parts.append('A' * b)
        else:
            parts.append('A' * (b - 1))

    if q:
        parts.append('W' * q)

    return ''.join(parts)

