class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        sets = [set(p) for p in properties]

        parent = list(range(n))

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: int, b: int) -> None:
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb

        for i in range(n):
            si = sets[i]
            for j in range(i + 1, n):
                if len(si & sets[j]) >= k:
                    union(i, j)

        return len({find(i) for i in range(n)})

class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        vals = [ord(ch) - ord('a') for ch in s]

        dp = [[None] * n for _ in range(n)]
        for i in range(n):
            dp[i][i] = [1] * (k + 1)

        zeros = [0] * (k + 1)

        for length in range(2, n + 1):
            for i in range(0, n - length + 1):
                j = i + length - 1
                diff = abs(vals[i] - vals[j])
                dist = diff if diff <= 13 else 26 - diff

                skip_left = dp[i + 1][j]
                skip_right = dp[i][j - 1]
                inner = dp[i + 1][j - 1] if length >= 3 else zeros

                arr = [0] * (k + 1)
                for budget in range(k + 1):
                    best = skip_left[budget]
                    v = skip_right[budget]
                    if v > best:
                        best = v
                    if budget >= dist:
                        val = 2 + inner[budget - dist]
                        if val > best:
                            best = val
                    arr[budget] = best

                dp[i][j] = arr

        return dp[0][n - 1][k]

